package dev.sarp.gharchive;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.zip.GZIPInputStream;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import dev.sarp.gharchive.model.GithubEvent;

public class App {
    public String getGreeting() {
        return "Hello World!";
    }

    // Pre work, testing the file opening and parsing
    public static void pre_fileWorker() {
        Path path = Path.of(
                "src/main/resources/githubData/2024-01-15-12.json.gz");

        try (
                var file = Files.newInputStream(path);
                var gzip = new GZIPInputStream(file);
                var text = new InputStreamReader(gzip, StandardCharsets.UTF_8);
                var reader = new BufferedReader(text)) {
            String line;
            int count = 0;

            ObjectMapper mapper = new ObjectMapper();

            long watchEventCount = 0;
            long pushEventCount = 0;
            long forkEventCount = 0;
            long allEventsCount = 0;
            long otherEventCount = 0;
            long validEventCount = 0;
            long invalidEventCount = 0;
            while ((line = reader.readLine()) != null) {
                allEventsCount++;
                try {

                    // Who is json
                    JsonNode event = mapper.readTree(line);

                    if (event == null) {
                        invalidEventCount++;
                        continue;
                    }

                    JsonNode typeNode = event.path("type");

                    if (!typeNode.isTextual() || typeNode.asText().isBlank()) {
                        invalidEventCount++;
                        continue;
                    }

                    String type = typeNode.asText();
                    validEventCount++;
                    String eventId = event.path("id").asText();

                    Instant createdAt = Instant.parse(
                            event.path("created_at").asText());

                    long repoId = event.path("repo").path("id").asLong();
                    String repoName = event.path("repo").path("name").asText();

                    long actorId = event.path("actor").path("id").asLong();
                    //System.out.println(type + " | " + repoName + " | " + createdAt);
                    var testDto = new GithubEvent(eventId, type, createdAt, repoId, repoName, actorId);
                    
                    switch (type) {
                        case "WatchEvent" -> watchEventCount++;
                        case "PushEvent" -> pushEventCount++;
                        case "ForkEvent" -> forkEventCount++;
                        default -> otherEventCount++;
                    }
                    if (allEventsCount <= 5) {
                        System.out.println(testDto);
                    }
                   

                } catch (JsonProcessingException e) {
                    // TODO: handle exception
                    invalidEventCount++;
                }

            }
            System.out.println("push event count : " + pushEventCount +
                    " | watch event count : " + watchEventCount +
                    " | fork event count: " + forkEventCount +
                    " | other event count : " + otherEventCount +
                    " | all event count : " + allEventsCount +
                    " | valid: " + validEventCount +
                    " | invalid: " + invalidEventCount);

        } catch (Exception e) {
            // TODO: handle exception
            System.out.println("Shit happend");
        }

    }

    public static void main(String[] args) {
        System.out.println(new App().getGreeting());
        pre_fileWorker();
    }
}
